import { generateDiagram } from '../../core/diagrams/generateDiagram';
import { createStoredDiagram, importDiagramRevision, getDiagramRevision, submitStoredDiagramEdit } from '../../../domain/core/diagrams/diagramRevisionStore';
import type { GeneratedDiagramEdit } from '../../../domain/core/diagrams/generatedDiagramEdit';
import { selectionExcerpt } from '../../../domain/mapping/workspace/selectionClipboard';
import { diagramContentNodes } from '../../../domain/core/diagrams/diagramContentNodes';
import { diagramReplacementRanges } from '../../../domain/core/diagrams/diagramSubtreeEdit';
import { revisionScope, reviewRevisionIds, validateRevisionReview, type DiagramRevisionReview } from '../../../domain/core/diagrams/diagramRevisionReview';
import { validateConnectionAnchor } from '../../../domain/core/diagrams/diagramConnection';
import { AgentContext, type AgentContextSnapshot } from '../../../domain/core/agents/agentContext';
import { diagramContextSourceFingerprint, loadDiagramAgentContext, type DiagramAgentContextStore } from '../../../domain/core/diagrams/diagramAgentContext';
import { randomUUID } from 'node:crypto';
import { CanvasHistory, type CanvasHistoryRecord } from '../../../domain/core/diagrams/canvasHistory';
import type { DiagramGenerator } from '../../../domain/core/diagrams/diagramGeneration';
import type { DiagramRevisionResult, DiagramRevision } from '../../../domain/core/diagrams/diagramRevision';
import type { GridBox } from '../../../domain/core/diagrams/lineGrid';
import type { LiveDocumentSnapshot } from '../../../domain/mapping/agent/contracts';
import { editDiagramSchema } from '../../../domain/mapping/agent/diagramEdit';
import type { CreateDiagramInput, DiagramCreation, DiagramEditRun, DiagramRevisionApplication, EditDiagramInput, PromptReference } from '../../../domain/mapping/agent/diagramEdit';
import { defaultTemplateSelection, resolvePromptTemplate, type PromptOperation } from '../../../domain/mapping/agent/promptTemplates';
import { findBox } from '../../../domain/mapping/workspace/canvasDisplayNode';
import { diagramSelectionNodes } from '../../../domain/mapping/workspace/mappingDocument';

export interface DiagramEditCanvasPort {
  snapshot(sessionId: string, revisionIds?: string[]): Promise<LiveDocumentSnapshot>;
  apply(sessionId: string, input: DiagramRevisionApplication): Promise<{ version: number; unresolvedEdgeIds: string[] }>;
  /** Idempotent per requestId. Optional: runtimes without it reject create-diagram. */
  create?(sessionId: string, input: { requestId: string; expectedVersion: number; diagrams: DiagramCreation[] }): Promise<{ version: number }>;
}
interface Run {
  variants?: DiagramRevisionApplication['variants'];
  submission?: GeneratedDiagramEdit;
  agentContext?: AgentContextSnapshot;
  nextAgentContext?: AgentContextSnapshot;
  input: CreateDiagramInput;
  signature: string;
  state: DiagramEditRun;
  abort: AbortController;
  revision?: DiagramRevisionResult;
  created?: DiagramRevisionResult[];
  pending?: Promise<void>;
}
/** A reference as the model receives it: the pinned revision's text, never the live canvas. */
export type ResolvedPromptReference = { ref: number; kind: PromptReference['kind']; label: string; diagramId: string; revisionId: string }
  & ({ kind: 'diagram'; ascii: string } | { kind: 'nodes'; range: Extract<PromptReference, { kind: 'nodes' }>['range']; excerpt: string; nodes: { id: string; label: string }[] });

/** A request owns both generation and installation; retries never rerun the model. */
export class DiagramEditService {
  private runs = new Map<string, Run>();
  private requests = new Map<string, string>();
  constructor(private readonly diagrams: DiagramGenerator, private readonly canvas: DiagramEditCanvasPort,
    private readonly diagramContexts?: DiagramAgentContextStore) {}

  start(input: EditDiagramInput | CreateDiagramInput, suppliedContext?: AgentContextSnapshot, operation: PromptOperation = 'edit-diagram', submission?: GeneratedDiagramEdit): DiagramEditRun {
    if (input['presentation-alternative'] && (operation !== 'edit-diagram' || input['edit-mode'] !== 'variant')) throw Error('presentation-alternative requires edit-diagram with edit-mode variant');
    if (operation === 'edit-diagram' && 'count' in input && input.count !== undefined) throw Error('count applies only to create-diagram');
    if (operation === 'edit-diagram') input = editDiagramSchema.parse(input);
    if (input.agentContext && (input.agentContextId || suppliedContext)) throw Error('Provide only one agent context source');
    if (input.agentContext && !input.llmSessionId) throw Error('Panel context requires llmSessionId');
    const rawContext = input.agentContext ?? suppliedContext;
    const agentContext = rawContext ? AgentContext.fromSnapshot(rawContext).toSnapshot() : undefined;
    if (input.llmSessionId && agentContext && !input.agentContextId?.startsWith('saved-agent-context-') && agentContext.source.sourceSessionId !== input.llmSessionId)
      throw Error('AGENT_CONTEXT_SESSION_MISMATCH: context belongs to another panel');
    if (input.agentContextId && !agentContext) throw Error('AGENT_CONTEXT_NOT_FOUND: resolve context before starting the edit');
    if (operation !== 'edit-diagram' && !this.canvas.create) throw Error('Diagram creation UNAVAILABLE in this runtime');
    if (input.variant && operation !== 'edit-diagram') throw Error('Variants require edit-diagram');
    if (input['edit-mode'] !== undefined && operation !== 'edit-diagram') throw Error('edit-mode applies only to edit-diagram');
    if (input['edit-mode'] === 'in-place' && input.variant) throw Error('in-place mode cannot include variant options');
    if (operation !== 'edit-diagram' && (input['replace-mode'] || input.subtree || input.subtrees)) throw Error('Replacement scope applies only to edit-diagram');
    if (submission && (input.variant && input.variant.count !== 1 || 'count' in input && input.count && input.count !== 1)) throw Error('Use one batch operation per submitted diagram or variant');
    if (input.variant?.variantId && input.variant.count !== 1) throw Error('Refine one existing variant at a time');
    if (operation === 'extend-diagram' && (!input.origin || !input.sources?.length)) throw Error('Extend requires a selection and a canvas origin');
    // Fail fast on an unknown template or invalid options instead of after a model call.
    resolvePromptTemplate(input.template ?? defaultTemplateSelection(operation), operation);
    const key = JSON.stringify([input.sessionId, input.requestId]);
    const signature = JSON.stringify({ operation, input, submission, agentContextHash: agentContext?.contentHash });
    const existing = this.requests.get(key);
    if (existing) {
      const run = this.runs.get(existing)!;
      if (run.signature !== signature) throw Error('REQUEST_ID_CONFLICT: edit request differs');
      if (run.state.status === 'awaiting-acknowledgement' && !run.pending) this.launch(run, () => this.install(run));
      return structuredClone(run.state);
    }
    if (this.runs.size >= 500) throw Error('Diagram edit run capacity reached; restart the backend');
    const run: Run = { submission, agentContext, input: structuredClone(input), signature, abort: new AbortController(), state: {
      ...(input.agentContextId ? { agentContextId: input.agentContextId, agentContextHash: agentContext!.contentHash } : {}),
      runId: `diagram-edit-${randomUUID()}`, operation, status: 'generating', nodeId: input.nodeId, baseRevisionId: input.baseRevisionId
    } };
    this.runs.set(run.state.runId, run); this.requests.set(key, run.state.runId);
    this.launch(run, () => this.generate(run));
    return structuredClone(run.state);
  }
  async wait(id: string) { const run = this.runs.get(id); if (!run) throw Error('Diagram edit run not found'); await run.pending; return this.get(id); }
  get(id: string) {
    const run = this.runs.get(id); if (!run) throw Error('Diagram edit run not found');
    return structuredClone(run.state);
  }
  cancel(id: string) {
    const run = this.runs.get(id); if (!run) throw Error('Diagram edit run not found');
    // Once application is dispatched its outcome can be unknown. Never call it cancelled.
    if (run.state.status === 'generating') {
      run.abort.abort(); run.state.status = 'cancelled'; run.state.message = 'Cancelled before application';
    }
    return structuredClone(run.state);
  }
  private launch(run: Run, work: () => Promise<void>) {
    run.pending = work().catch(error => {
      if (run.abort.signal.aborted && run.state.status !== 'applying') { run.state.status = 'cancelled'; return; }
      const message = error instanceof Error ? error.message : String(error);
      run.state.status = run.state.status === 'applying' && /CANVAS_TIMEOUT|CANVAS_UNAVAILABLE|PERSISTENCE_PENDING/.test(message)
        ? 'awaiting-acknowledgement' : message.includes('VERSION_CONFLICT') ? 'conflict' : 'failed';
      run.state.error = message;
    }).finally(() => { run.pending = undefined; });
  }
  private install(run: Run) { return run.state.operation !== 'edit-diagram' ? this.place(run) : this.apply(run); }
  private async generate(run: Run) {
    const { input, abort } = run, operation = run.state.operation;
    const snapshot = await this.canvas.snapshot(input.sessionId, [...(input.baseRevisionId && input.baseRevisionId !== 'canvas' ? [input.baseRevisionId] : []), ...(input.references ?? []).map(ref => ref.revisionId)]);
    abort.signal.throwIfAborted();
    if (snapshot.version !== input.expectedVersion) throw Error('VERSION_CONFLICT: read the canvas again');
    const box = input.nodeId.startsWith('grid:') && findBox(snapshot.document.scene.root, input.nodeId.slice(5));
    const unanchored = operation === 'create-diagram' && input.nodeId === 'canvas';
    if (!unanchored && (!box || box.kind !== 'diagram')) throw Error('Expected diagram GridBox');
    let base = box && box.kind === 'diagram' ? snapshot.document.scene.contents[box.contentId]
      : createStoredDiagram({ id: `context-${randomUUID()}`, revision: 0, ascii: '[New diagram]' }).diagram;
    if (!unanchored && base.revisionId !== input.baseRevisionId) throw Error('VERSION_CONFLICT: diagram base is no longer current');
    if (!run.submission && !run.agentContext && operation === 'edit-diagram') {
      const bound = snapshot.document.diagramContexts?.[base.diagramId];
      if (bound && bound.sourceFingerprint === diagramContextSourceFingerprint(base))
        run.agentContext = await loadDiagramAgentContext(bound, this.diagramContexts);
    }
    // Import only the exact target/reference revisions, including their logical node identities.
    for (const revision of snapshot.revisions ?? []) importDiagramRevision(revision);
    // Compatibility for in-process adapters that still supply a history record.
    if (!snapshot.revisions && snapshot.history) new CanvasHistory(snapshot.document, snapshot.canvas, snapshot.history, 'current');
    const existing = input.variant?.variantId ? snapshot.document.revisionReviews?.[input.variant.variantId] : undefined;
    if (input.variant?.variantId && !existing) throw Error('Variant not found');
    if (existing) {
      if (existing.diagramId !== base.diagramId) throw Error('Variant belongs to another diagram');
      const retained = await this.canvas.snapshot(input.sessionId, reviewRevisionIds(existing));
      for (const revision of retained.revisions ?? []) importDiagramRevision(revision);
      if (retained.version !== input.expectedVersion) throw Error('VERSION_CONFLICT: canvas changed');
      base = getDiagramRevision(existing.headRevisionId).diagram;
    }
    const template = resolvePromptTemplate(input.template ?? defaultTemplateSelection(operation), operation);
    const references = this.resolveReferences(input.references ?? [], snapshot.history);
    const lines = base.content.ascii.split('\n');
    const editRanges = operation === 'edit-diagram'
      ? existing ? (() => {
        if (input.subtree || input.subtrees) throw Error('Refinement uses the saved variant scope; omit subtree targets');
        if (existing.replacementScope) {
          if (input['replace-mode'] !== existing.replacementScope.mode) throw Error('replace-mode must match the saved variant scope');
          if (existing.replacementScope.ranges.some(range => range.endLine < range.startLine)) throw Error('The saved replacement scope was deleted; select new targets for a new edit');
          return existing.replacementScope.ranges;
        }
        const range = existing.ownerNodeId === 'root' ? undefined : revisionScope(getDiagramRevision(base.revisionId), existing.ownerNodeId);
        if (input['replace-mode'] !== (range ? 'subnode-single' : 'diagram')) throw Error('replace-mode must match the saved variant scope');
        return range ? [range] : [];
      })() : diagramReplacementRanges(base, input['replace-mode']!, input.subtree, input.subtrees)
      : [];
    const editRange = editRanges.length === 1 ? editRanges[0] : undefined;
    if (operation === 'extend-diagram') for (const source of input.sources!) validateConnectionAnchor(snapshot.document.scene, source);
    const request = { operation, sourceMappings: input['source-mappings'] ?? false, editRange, editRanges, instruction: input.prompt, agentContext: run.agentContext, llmSessionId: input.llmSessionId,
      prompt: { markdown: template.markdown, options: template.options, parameters: template.definition.parameters, references },
      context: { diagram: base, selection: { startLine: 1, endLine: lines.length, startColumn: 1,
        endColumn: Math.max(1, ...lines.map(line => line.length)) }, connections: snapshot.document.edges } };
    const options = { signal: abort.signal, onAgentSession: (id: string) => { run.state.agentSessionId = id; },
      onAgentContext: (context: AgentContextSnapshot) => {
        const next = AgentContext.fromSnapshot(context).toSnapshot();
        if (next.source.sourceSessionId !== input.llmSessionId) throw Error('AGENT_CONTEXT_SESSION_MISMATCH');
        run.nextAgentContext = next;
      }, onProgress: (message: string) => { if (run.state.status === 'generating') run.state.message = message; } };
    const produce = (request: Parameters<DiagramGenerator['generate']>[0], options: Parameters<DiagramGenerator['generate']>[1]) =>
      run.submission ? Promise.resolve(submitStoredDiagramEdit(request, run.submission)) : generateDiagram(this.diagrams, request, options);
    if (operation !== 'edit-diagram') {
      run.created = [];
      for (let index = 0; index < (operation === 'extend-diagram' ? 1 : input.count ?? 1); index++) {
        if (input.count && input.count > 1) options.onProgress(`Generating diagram ${index + 1} of ${input.count}…`);
        run.created.push(await produce({ ...request, agentContext: run.nextAgentContext ?? run.agentContext, input: { id: `diagram-${randomUUID()}`, structureKind: base.content.structure.kind,
          source: base.sourceContext.binding, evidence: base.sourceContext.evidence } }, options));
        abort.signal.throwIfAborted();
      }
      await this.place(run);
      return;
    }
    // Keep the existing panel's variant creation/refinement contract supported.
    const variantOptions = input['edit-mode'] === 'variant' ? input.variant ?? { name: 'Alternative', count: 1 } : undefined;
    if (variantOptions) {
      run.variants = [];
      const ownerNodeId = existing?.ownerNodeId ?? (input.subtree ? getDiagramRevision(base.revisionId).nodeRefs[input.subtree.contentNodeId] : 'root');
      if (!ownerNodeId) throw Error('STALE_SUBTREE: select a current subtree');
      for (let index = 0; index < variantOptions.count; index++) {
        options.onProgress(`Generating variant ${index + 1} of ${variantOptions.count}…`);
        const generated = await produce({ ...request,
          instruction: input.prompt + (variantOptions.count > 1 ? `\nProduce alternative ${index + 1} of ${variantOptions.count}; explore a distinct approach.` : ''),
          baseRevisionId: base.revisionId, input: { id: base.id, structureKind: base.content.structure.kind,
            source: base.sourceContext.binding, evidence: base.sourceContext.evidence } }, options);
        abort.signal.throwIfAborted();
        const variant: DiagramRevisionReview = { ...existing, id: existing?.id ?? `variant-${randomUUID()}`,
          name: variantOptions.name + (variantOptions.count > 1 ? ` ${index + 1}` : ''), diagramId: base.diagramId, contentId: base.id,
          ...(input['replace-mode'] === 'multi-contiguous' || input['replace-mode'] === 'multi-disjoint'
            ? { replacementScope: { mode: input['replace-mode'], ranges: generated.replacementRanges! } } : {}),
          ownerNodeId, baseRevisionId: existing?.baseRevisionId ?? base.revisionId, headRevisionId: generated.revision.id,
          revisionIds: [...(existing?.revisionIds ?? []), generated.revision.id], prompt: input.prompt, decisions: {} };
        validateRevisionReview(variant, id => getDiagramRevision(id));
        const promotion = input['presentation-alternative'];
        const targets = input.subtrees ?? (input.subtree ? [input.subtree] : []);
        const owners = targets.length ? targets.map(target => getDiagramRevision(base.revisionId).nodeRefs[target.contentNodeId]) : ['root'];
        run.variants.push({ variant, revision: generated.revision, ...(promotion ? {
          alternative: { id: `alternative-${randomUUID()}`, name: promotion.name + (variantOptions.count > 1 ? ` ${index + 1}` : ''),
            diagramId: base.diagramId, presentationId: input.nodeId, reviewId: variant.id,
            parts: owners.map(owner => ({ target: ownerScope(owner), source: { revisionId: generated.revision.id, scope: ownerScope(owner) }, baseRevisionId: base.revisionId })) },
          selectAlternative: promotion.select && index === 0 } : {}) });
        run.revision = generated;
      }
      await this.apply(run); return;
    }
    run.revision = await produce({ ...request, baseRevisionId: base.revisionId, input: { id: base.id,
      structureKind: base.content.structure.kind, source: base.sourceContext.binding, evidence: base.sourceContext.evidence } }, options);
    abort.signal.throwIfAborted();
    run.state.generated = { diagramId: run.revision.diagram.diagramId, revisionId: run.revision.revision.id,
      ascii: run.revision.diagram.content.ascii };
    await this.apply(run);
  }
  /** References resolve against the canvas's own revision history first; the service registry covers revisions it issued. */
  private resolveReferences(references: readonly PromptReference[], history?: CanvasHistoryRecord): ResolvedPromptReference[] {
    return references.map((reference, index) => {
      const ref = index + 1;
      let revision: DiagramRevision | undefined = history?.diagramRevisions[reference.revisionId];
      if (!revision) try { revision = getDiagramRevision(reference.revisionId); } catch { /* reported below */ }
      if (!revision || revision.diagramId !== reference.diagramId) throw Error(`PROMPT_REFERENCE_NOT_FOUND: [ref ${ref}] ${reference.label} is not available`);
      const common = { ref, label: reference.label, diagramId: reference.diagramId, revisionId: reference.revisionId };
      if (reference.kind === 'diagram') return { ...common, kind: 'diagram', ascii: revision.diagram.content.ascii };
      const lines = revision.diagram.content.ascii.split('\n'), range = reference.range;
      if (range.endLine > lines.length) throw Error(`PROMPT_REFERENCE_INVALID: [ref ${ref}] range is outside its revision`);
      const known = new Map([...diagramSelectionNodes(revision.diagram), ...diagramContentNodes(revision.diagram.content)].map(node => [node.id, node.label]));
      const unknown = reference.nodeIds.find(id => !known.has(id));
      if (unknown) throw Error(`PROMPT_REFERENCE_INVALID: [ref ${ref}] node ${unknown} is not in its revision`);
      return { ...common, kind: 'nodes', range,
        excerpt: reference.nodeIds.length && reference.nodeIds.every(id => diagramContentNodes(revision.diagram.content).some(node => node.id === id))
          ? selectionExcerpt(revision.diagram, range, reference.nodeIds)
          : lines.slice(range.startLine - 1, range.endLine).map(line => line.slice(range.startColumn - 1, range.endColumn).trimEnd()).join('\n'),
        nodes: reference.nodeIds.map(id => ({ id, label: known.get(id)! })) };
    });
  }
  private async apply(run: Run) {
    run.state.status = 'applying'; delete run.state.error;
    const revision = run.revision!.revision, input = run.input;
    // The controller checks both versions at the mutation boundary, after generation.
    const result = await this.canvas.apply(input.sessionId, { requestId: run.state.runId,
      expectedVersion: input.expectedVersion, nodeId: input.nodeId, baseRevisionId: input.baseRevisionId, revision,
      ...(run.variants ? { variants: run.variants } : {}) });
    if (run.variants) run.state.variants = run.variants.map(({ variant, alternative }) => ({ id: variant.id, name: variant.name, revisionId: variant.headRevisionId, ...(alternative ? { alternativeId: alternative.id } : {}) }));
    run.state.result = { diagramId: revision.diagramId, previousRevisionId: input.baseRevisionId,
      revisionId: revision.id, documentVersion: result.version, unresolvedEdgeIds: result.unresolvedEdgeIds };
    run.state.agentContext = run.nextAgentContext;
    run.state.status = 'completed'; run.state.message = run.variants
      ? 'Diagram variants saved and workspace persisted' : 'Diagram revision installed and workspace persisted';
  }
  /** New diagrams never conflict with canvas edits: placement reads the latest version and sits beside the anchor. */
  private async place(run: Run) {
    run.state.status = 'applying'; delete run.state.error;
    for (let attempt = 1; ; attempt++) {
      try { return await this.placeOnce(run); }
      catch (error) { if (attempt >= 3 || !String(error).includes('VERSION_CONFLICT')) throw error; }
    }
  }
  private async placeOnce(run: Run) {
    const snapshot = await this.canvas.snapshot(run.input.sessionId);
    if (run.state.operation === 'extend-diagram') for (const source of run.input.sources!) validateConnectionAnchor(snapshot.document.scene, source);
    const anchorId = run.input.nodeId.slice(5), parent = findParent(snapshot.document.scene.root, anchorId);
    const anchor = parent?.children.find(child => child.id === anchorId);
    const width = (ascii: string) => Math.max(1, ...ascii.split('\n').map(line => line.length)) + 2;
    let column = anchor ? anchor.position.column + width(anchor.kind === 'diagram' ? snapshot.document.scene.contents[anchor.contentId]?.content.ascii ?? '' : '') + 4 : 0;
    const diagrams = run.created!.map(created => {
      const { diagram } = created, position = run.input.origin ?? { column, row: anchor?.position.row ?? 0 };
      column += width(diagram.content.ascii) + 4;
      return { id: diagram.id, position, ...(run.state.operation === 'extend-diagram' ? { sources: run.input.sources } : {}), ...(run.input.origin ? {} : parent && parent.id !== snapshot.document.scene.root.id ? { parentId: `grid:${parent.id}` } : {}),
        content: { ascii: diagram.content.ascii, structureKind: diagram.content.structure.kind, mappings: diagram.sourceContext.mappings,
          evidence: diagram.sourceContext.evidence, source: diagram.sourceContext.binding } } as DiagramCreation;
    });
    const result = await this.canvas.create!(run.input.sessionId, { requestId: run.state.runId, expectedVersion: snapshot.version, diagrams });
    run.state.created = { documentVersion: result.version, nodeIds: diagrams.map(diagram => `grid:${diagram.id}`) };
    run.state.agentContext = run.nextAgentContext;
    run.state.status = 'completed'; run.state.message = `${diagrams.length === 1 ? 'Diagram' : `${diagrams.length} diagrams`} created beside the anchor`;
  }
  dispose() { for (const run of this.runs.values()) this.cancel(run.state.runId); }
}

function findParent(box: GridBox, id: string): Extract<GridBox, { kind: 'container' }> | undefined {
  if (box.kind !== 'container') return undefined;
  return box.children.some(child => child.id === id) ? box : box.children.map(child => findParent(child, id)).find(Boolean);
}
"},{"path":"application/mapping/agent/diagramBatchService.ts","text":"import { randomUUID } from 'node:crypto';
import type { DiagramGenerator } from '../../../domain/core/diagrams/diagramGeneration';
import type { DiagramAgentContextStore } from '../../../domain/core/diagrams/diagramAgentContext';
import { DiagramEditService, type DiagramEditCanvasPort } from './diagramEditService';
import { directBatchSchemas, generationBatchSchemas, type DiagramBatchApplication, type DiagramBatchRun, type DiagramTool } from '../../../domain/mapping/agent/diagramBatch';
import { findBox } from '../../../domain/mapping/workspace/canvasDisplayNode';

interface Batch { signature: string; state: DiagramBatchRun; pending?: Promise<void>; child?: DiagramEditService; childRunId?: string; application?: DiagramBatchApplication; sessionId: string }
export class DiagramBatchService {
  private runs = new Map<string, Batch>();
  private requests = new Map<string, string>();
  constructor(private diagrams: DiagramGenerator, private canvas: DiagramEditCanvasPort & {
    batch(sessionId: string, input: DiagramBatchApplication): Promise<{ version: number; unresolvedEdgeIds: string[] }>
  }, private contexts?: DiagramAgentContextStore, private contextFor?: (sessionId: string, contextId: string) => import('../../../domain/core/agents/agentContext').AgentContextSnapshot | Promise<import('../../../domain/core/agents/agentContext').AgentContextSnapshot>) {}
  has(id: string) { return this.runs.has(id); }
  get(id: string) { const batch = this.runs.get(id); if (!batch) throw Error('Batch not found'); return structuredClone(batch.state); }
  async wait(id: string) { await this.runs.get(id)?.pending; return this.get(id); }
  cancel(id: string) {
    const batch = this.runs.get(id); if (!batch) throw Error('Batch not found');
    if (batch.state.status === 'generating') { batch.state.status = 'cancelled'; if (batch.childRunId) batch.child?.cancel(batch.childRunId); }
    return this.get(id);
  }
  start(raw: unknown, operation: DiagramTool, direct: boolean) {
    const input = (direct ? directBatchSchemas : generationBatchSchemas)[operation].parse(raw);
    const key = JSON.stringify([input.sessionId, input.requestId]), signature = JSON.stringify({ input, operation, direct });
    const old = this.requests.get(key);
    if (old) {
      const batch = this.runs.get(old)!;
      if (batch.signature !== signature) throw Error('REQUEST_ID_CONFLICT: batch arguments differ');
      if (batch.state.status === 'awaiting-acknowledgement' && !batch.pending) this.launch(batch, () => this.apply(batch));
      return this.get(old);
    }
    if (this.runs.size >= 500) throw Error('Diagram batch capacity reached; restart backend');
    const runId = `diagram-batch-${randomUUID()}`;
    const batch: Batch = { signature, sessionId: input.sessionId, state: { runId, operation, status: 'generating', results: [] } };
    this.runs.set(runId, batch); this.requests.set(key, runId);
    this.launch(batch, async () => {
      const revisions = input.operations.flatMap(item => [item.baseRevisionId, ...('references' in item ? item.references ?? [] : []).map(ref => ref.revisionId)]);
      const snapshot = await this.canvas.snapshot(input.sessionId, revisions.filter(id => id !== 'canvas'));
      if (snapshot.version !== input.expectedVersion) throw Error('VERSION_CONFLICT: reread the canvas');
      const application: DiagramBatchApplication = { requestId: runId, expectedVersion: input.expectedVersion, edits: [], creations: [] };
      // All inputs address the same snapshot. Multiple edits of one shared diagram would be ambiguous.
      const targets = new Set<string>();
      for (let index = 0; index < input.operations.length; index++) {
        batch.state.operationIndex = index;
        const item = input.operations[index], box = findBox(snapshot.document.scene.root, item.nodeId.slice(5));
        if (operation === 'edit-diagram' && box?.kind === 'diagram') {
          const id = snapshot.document.scene.contents[box.contentId].diagramId;
          if (targets.has(id)) throw Error('BATCH_TARGET_CONFLICT: combine edits to the same diagram in one operation');
          targets.add(id);
        }
      }
      let autoOffset = 0;
      for (let index = 0; index < input.operations.length; index++) {
        if (batch.state.status === 'cancelled') return;
        batch.state.operationIndex = index;
        const item = input.operations[index];
        const child = new DiagramEditService(this.diagrams, {
          snapshot: async (_id, ids) => {
            const extra = (ids ?? []).filter(id => id !== 'canvas' && !snapshot.revisions?.some(revision => revision.id === id));
            const retained = extra.length ? await this.canvas.snapshot(input.sessionId, extra) : undefined;
            if (retained && retained.version !== snapshot.version) throw Error('VERSION_CONFLICT: canvas changed');
            return { ...snapshot, revisions: [...(snapshot.revisions ?? []), ...(retained?.revisions ?? [])] };
          },
          apply: async (_id, edit) => { application.edits.push(edit); return { version: snapshot.version, unresolvedEdgeIds: [] }; },
          create: async (_id, creation) => {
            for (const diagram of creation.diagrams) {
              if (!item.origin) { diagram.position.column += autoOffset; autoOffset += Math.max(...diagram.content.ascii.split('\n').map(line => line.length)) + 6; }
              application.creations.push(diagram);
            }
            return { version: snapshot.version };
          }
        }, this.contexts);
        batch.child = child;
        const { edit, diagram, ...fields } = item as typeof item & { edit?: import('../../../domain/core/diagrams/generatedDiagramEdit').GeneratedDiagramEdit; diagram?: import('../../../domain/core/diagrams/generatedDiagramEdit').GeneratedDiagramEdit };
        const context = 'agentContextId' in fields && fields.agentContextId ? await this.contextFor?.(input.sessionId, fields.agentContextId) : undefined;
        if (this.get(runId).status === 'cancelled') return;
        const childRun = child.start({ ...fields, prompt: 'prompt' in fields ? fields.prompt : 'Apply supplied diagram',
          sessionId: input.sessionId, expectedVersion: snapshot.version, requestId: `${runId}:${index}` }, context, operation, direct ? edit ?? diagram : undefined);
        batch.childRunId = childRun.runId;
        const result = await child.wait(childRun.runId);
        if (this.get(runId).status === 'cancelled') return;
        if (result.status !== 'completed') throw Error(result.error ?? `Operation ${index} ${result.status}`);
        batch.state.results.push({ operationIndex: index, ...(result.agentContextId ? { agentContextId: result.agentContextId, agentContextHash: result.agentContextHash } : {}), result: result.result, variants: result.variants, created: result.created });
      }
      batch.child = undefined; batch.childRunId = undefined; delete batch.state.operationIndex;
      batch.application = application;
      await this.apply(batch);
    });
    return this.get(runId);
  }
  private launch(batch: Batch, work: () => Promise<void>) {
    batch.pending = work().catch(error => {
      if (batch.state.status === 'cancelled') return;
      const message = String(error);
      batch.state.status = batch.state.status === 'applying' && /PERSISTENCE_PENDING|CANVAS_TIMEOUT|CANVAS_UNAVAILABLE/.test(message)
        ? 'awaiting-acknowledgement' : message.includes('VERSION_CONFLICT') ? 'conflict' : 'failed';
      batch.state.error = `${batch.state.operationIndex === undefined ? '' : `operations[${batch.state.operationIndex}]: `}${message}`;
    }).finally(() => { batch.pending = undefined; });
  }
  private async apply(batch: Batch) {
    batch.state.status = 'applying'; delete batch.state.error;
    const receipt = await this.canvas.batch(batch.sessionId, batch.application!);
    for (const result of batch.state.results) {
      if (result.result) { result.result.documentVersion = receipt.version; result.result.unresolvedEdgeIds = receipt.unresolvedEdgeIds; }
      if (result.created) result.created.documentVersion = receipt.version;
    }
    batch.state.documentVersion = receipt.version; batch.state.status = 'completed';
  }
  dispose() { for (const id of this.runs.keys()) this.cancel(id); }
}
"},{"path":"application/core/agents/agentWorkflow.ts","text":"/** Feature-owned prompts and validation; session/tool ownership stays with the executor. */
export interface AgentWorkflowStep<T> {
  id: string;
  prompt(previous: T | undefined): string;
  before?(previous: T | undefined): void | Promise<void>;
  validate?(output: T, previous: T | undefined): void | Promise<void>;
}

export interface AgentWorkflow<T> {
  id: string;
  steps: readonly AgentWorkflowStep<T>[];
}

export interface AgentStepRequest {
  workflowId: string;
  stepId: string;
  prompt: string;
  signal?: AbortSignal;
}

/** Return only this turn's accepted submission. Honor signal for in-flight cancellation. */
export type AgentStepExecutor<T> = (request: AgentStepRequest) => Promise<T | undefined>;

export async function runAgentWorkflow<T>(
  workflow: AgentWorkflow<T>,
  execute: AgentStepExecutor<T>,
  options: { signal?: AbortSignal; onStepStart?(stepId: string): void } = {}
): Promise<T> {
  if (!workflow.id.trim() || !workflow.steps.length) throw new Error("An agent workflow needs an id and at least one step");
  const ids = new Set<string>();
  for (const step of workflow.steps) {
    if (!step.id.trim() || ids.has(step.id)) throw new Error(`Invalid or duplicate workflow step: ${step.id}`);
    ids.add(step.id);
  }

  let previous: T | undefined;
  for (const step of workflow.steps) {
    options.signal?.throwIfAborted();
    options.onStepStart?.(step.id);
    await step.before?.(previous);
    options.signal?.throwIfAborted();
    const output = await execute({
      workflowId: workflow.id, stepId: step.id, prompt: step.prompt(previous), signal: options.signal
    });
    options.signal?.throwIfAborted();
    if (output === undefined) throw new Error(`${workflow.id}/${step.id} finished without an accepted submission`);
    await step.validate?.(output, previous);
    options.signal?.throwIfAborted();
    previous = output;
  }
  return previous!;
}
"},{"path":"infrastructure/core/agents/agentRuntime.ts","text":"import { requireAiEnabled } from '../../../application/core/errors';
import type { AgentContext } from '../../../domain/core/agents/agentContext';
import { type Model } from "@earendil-works/pi-ai";
import { createAgentSession, SessionManager, type CreateAgentSessionOptions, ModelRuntime, type AgentSessionEvent } from "@earendil-works/pi-coding-agent";
import { DEFAULT_DIAGRAM_MODEL_ID, type AgentProgress } from "../../../domain/core/records/domain";
export function progressFor(event: AgentSessionEvent, model: string, sessionId: string): AgentProgress | undefined {
  const shared = { model, sessionId };
  if (event.type === "agent_start" || event.type === "turn_start" || event.type === "message_start") {
    return { ...shared, status: "generating", message: "agent is composing a structured result" };
  }
  if (event.type === "tool_execution_start") {
    if (["read", "grep", "find", "ls"].includes(event.toolName)) {
      return { ...shared, status: "reading-context", message: `inspecting source with ${event.toolName}` };
    }
    if (event.toolName.startsWith("submit_")) {
      return { ...shared, status: "validating", message: "validating structured submission" };
    }
  }
  return undefined;
}
export function createPersistedAgentSessionManager(cwd: string): SessionManager {
  // Keep Pi sessions on disk so prompts, tool calls, and usage remain auditable.
  // Do not switch back to in-memory sessions without explicit user approval.
  return SessionManager.create(cwd);
}
export class PiAgentRuntime {
  constructor(private readonly enabled = false) {}

  protected requireEnabled(): void { requireAiEnabled(this.enabled); }

  protected modelRuntime?: Promise<ModelRuntime>;

  protected readonly sessions = new Set<{ abort(): Promise<void>; dispose(): void }>();

  protected async createSession(configuration: Omit<CreateAgentSessionOptions, 'sessionManager'>, context?: AgentContext) {
    this.requireEnabled();
    const sessionManager = createPersistedAgentSessionManager(configuration.cwd ?? process.cwd());
    for (const message of context?.toPiMessages() ?? []) sessionManager.appendMessage(message);
    const result = await createAgentSession({ ...configuration, sessionManager });
    this.sessions.add(result.session);
    return result;
  }

  protected runtime(): Promise<ModelRuntime> {
    this.requireEnabled();
    this.modelRuntime ??= ModelRuntime.create({ allowModelNetwork: false });
    return this.modelRuntime;
  }

  protected async model(overrideModelId?: string): Promise<{
    runtime: ModelRuntime;
    model: Model<any>;
    provider: string;
    modelId: string;
  }> {
    const runtime = await this.runtime();
    const provider = "openai-codex";
    const modelId = overrideModelId || process.env.NEW_DIAGRAM_MODEL || DEFAULT_DIAGRAM_MODEL_ID;
    const model = runtime.getModel(provider, modelId);
    if (!model) throw new Error(`Pi model is unavailable: ${provider}/${modelId}`);
    if (!runtime.hasConfiguredAuth(provider)) {
      throw new Error(`Pi provider is not authenticated: ${provider}`);
    }
    return { runtime, model, provider, modelId };
  }
  dispose(): void {
    for (const session of this.sessions) { void session.abort(); session.dispose(); }
    this.sessions.clear();
  }
}
"},{"path":"infrastructure/core/agents/validatedSubmission.ts","text":"export interface ValidatedSubmissionOptions<T> {
  toolName: string;
  validate(candidate: T): Promise<string | undefined> | string | undefined;
  acceptedMessage(candidate: T): string;
  acceptedDetails?(candidate: T): Record<string, unknown>;
  correctionPrompt?: string;
}

export function createValidatedSubmission<T>(options: ValidatedSubmissionOptions<T>) {
  let accepted: T | undefined;

  return {
    promptGuideline: `Call ${options.toolName} with the final candidate. If it is rejected, correct the reported issues and call it again.`,

    get value(): T | undefined {
      return accepted;
    },

    async execute(_toolCallId: string, candidate: T) {
      const validationError = await options.validate(candidate);
      if (validationError) {
        const correction = options.correctionPrompt
          ? `${options.correctionPrompt} Then call ${options.toolName} again.`
          : `Correct the submission and call ${options.toolName} again.`;
        return {
          content: [{
            type: "text" as const,
            text: `Submission rejected: ${validationError}. ${correction}`
          }],
          details: { accepted: false },
          terminate: false
        };
      }

      accepted = candidate;
      return {
        content: [{ type: "text" as const, text: options.acceptedMessage(candidate) }],
        details: {
          accepted: true,
          ...options.acceptedDetails?.(candidate)
        },
        terminate: true
      };
    }
  };
}
"},{"path":"infrastructure/mapping/agents/diagram-edit/diagramEditRuntime.ts","text":"import { diagramContentNodes } from '../../../../domain/core/diagrams/diagramContentNodes';
import { scopedReplacements } from '../../../../domain/core/diagrams/diagramSubtreeEdit';
import { captureDiagramAgentContext } from './diagramAgentContext';
import type { AgentContextSources } from '../../../../application/core/ports/agentContextSources';
import { AgentContext } from '../../../../domain/core/agents/agentContext';
import { Type } from '@earendil-works/pi-ai';
import { DefaultResourceLoader, defineTool, getAgentDir, SettingsManager } from '@earendil-works/pi-coding-agent';
import type { DiagramGenerationRequest, DiagramGenerator, GenerationOptions } from '../../../../domain/core/diagrams/diagramGeneration';
import { validateGeneratedDiagramEdit, type GeneratedDiagramEdit } from '../../../../domain/core/diagrams/generatedDiagramEdit';
import { diagramOutputFormat, defaultTemplateSelection, renderPromptTemplate, resolvePromptTemplate } from '../../../../domain/mapping/agent/promptTemplates';
import { PiAgentRuntime, progressFor } from '../../../core/agents/agentRuntime';
import { createValidatedSubmission } from '../../../core/agents/validatedSubmission';

/** Renders the request's validated template; requests without one use the default edit template. */
export function renderDiagramEditPrompt(request: DiagramGenerationRequest) {
  if (!request.context) throw Error('Diagram generation requires captured context');
  const prompt = request.prompt ?? (() => {
    const template = resolvePromptTemplate(defaultTemplateSelection(request.operation ?? 'edit-diagram'), request.operation ?? 'edit-diagram');
    return { markdown: template.markdown, options: template.options, parameters: template.definition.parameters, references: [] };
  })();
  const ranges = request.editRanges?.length ? request.editRanges : request.editRange ? [request.editRange] : [];
  return renderPromptTemplate(prompt, {
    context: JSON.stringify({ baseRevisionId: request.baseRevisionId ?? null, diagram: request.context.diagram, editableRanges: ranges,
      logicalNodes: request.baseRevisionId ? diagramContentNodes(request.context.diagram.content).map(node => ({ line: node.line, nodeRef: request.nodeRefs?.[node.id] })) : [],
      generationOptions: prompt.options, connections: request.context.connections ?? [] }),
    references: JSON.stringify(prompt.references), instruction: JSON.stringify(request.instruction)
  }) + '\n\n' + diagramOutputFormat(request.operation ?? 'edit-diagram', request.sourceMappings ?? false);

}

export class PiDiagramEditRuntime extends PiAgentRuntime implements DiagramGenerator {
  constructor(private readonly sourceRoot: string, enabled = false, private readonly sources?: AgentContextSources) { super(enabled); }
  async generate(request: DiagramGenerationRequest, options: GenerationOptions) {
    this.requireEnabled();
    const base = request.context?.diagram;
    if (!base) throw Error('Diagram edit context is required');
    options.signal?.throwIfAborted();
    const configured = await this.model();
    const prompt = renderDiagramEditPrompt(request);
    const submission = createValidatedSubmission<GeneratedDiagramEdit>({
      toolName: 'submit_diagram_edit',
      validate: candidate => { try { const clean = validateGeneratedDiagramEdit(base, candidate, request.nodeRefs, request.sourceMappings); const ranges = request.editRanges?.length ? request.editRanges : request.editRange ? [request.editRange] : []; if (ranges.length) { if (clean.structureKind !== base.content.structure.kind) throw Error('REPLACEMENT_SCOPE: preserve structure kind'); scopedReplacements(base, clean.ascii, ranges, clean.replacementRanges); } } catch (error) { return String(error); } },
      acceptedMessage: () => 'Validated diagram edit submitted.'
    });
    const submit = defineTool({
      name: 'submit_diagram_edit', label: 'Submit diagram edit',
      description: 'Submit the complete revised ASCII and mappings into the supplied evidence.',
      promptSnippet: 'Submit a complete revised diagram', promptGuidelines: [submission.promptGuideline],
      parameters: Type.Object({
        ascii: Type.String({ minLength: 1, maxLength: 200000 }),
        replacementRanges: Type.Optional(Type.Array(Type.Object({ startLine: Type.Integer({ minimum: 1 }), endLine: Type.Integer({ minimum: 0 }) }), { minItems: 1, maxItems: 100 })),
        structureKind: Type.Union([Type.Literal('diagram'), Type.Literal('tree')]),
        mappings: Type.Optional(Type.Array(Type.Object({
          id: Type.String(), entityId: Type.String(), sourceRangeIndex: Type.Integer({ minimum: 0 }),
          sourceRangeId: Type.Optional(Type.String()), line: Type.Integer({ minimum: 1 }),
          startColumn: Type.Integer({ minimum: 1 }), endColumn: Type.Integer({ minimum: 1 })
        }), { maxItems: 2000 }))
      }),
      execute: (id, candidate) => submission.execute(id, candidate)
    });
    const settingsManager = SettingsManager.inMemory({
      defaultProvider: configured.provider,
      defaultModel: configured.modelId, defaultThinkingLevel: 'medium'
    });
    const resourceLoader = new DefaultResourceLoader({
      cwd: this.sourceRoot, agentDir: getAgentDir(), settingsManager,
      noExtensions: true, noSkills: true, noPromptTemplates: true, noThemes: true, noContextFiles: true,
      systemPrompt: 'You create and edit ASCII diagrams using captured context. Follow the specification and finish with a validated submit_diagram_edit tool call.'
    });
    await resourceLoader.reload(); options.signal?.throwIfAborted();
    const imported = request.agentContext ? AgentContext.fromSnapshot(request.agentContext) : undefined;
    const agentContext = imported ? await imported.resolveSources(this.sources ? ref => this.sources!.read(ref) : undefined) : undefined;
    options.signal?.throwIfAborted();
    const { session } = await this.createSession({
      cwd: this.sourceRoot, modelRuntime: configured.runtime, model: configured.model,
      thinkingLevel: 'medium', tools: ['submit_diagram_edit'], customTools: [submit], resourceLoader, settingsManager
    }, agentContext);
    options.onAgentSession?.(session.sessionId);
    const unsubscribe = session.subscribe(event => {
      const progress = progressFor(event, `${configured.provider}/${configured.modelId}`, session.sessionId);
      if (progress) options.onProgress?.(progress.message);
    });
    const abort = () => { void session.abort().catch(() => { }); };
    options.signal?.addEventListener('abort', abort, { once: true });
    try {
      options.signal?.throwIfAborted();
      await session.prompt(prompt);
      options.signal?.throwIfAborted();
      if (!submission.value) throw Error('Diagram edit agent finished without a validated submission');
      const candidate = validateGeneratedDiagramEdit(base, submission.value, request.nodeRefs, request.sourceMappings);
      if (request.llmSessionId) options.onAgentContext?.(captureDiagramAgentContext(request.llmSessionId, session.messages, imported && agentContext ? { original: imported, resolved: agentContext } : undefined));
      return { ...candidate, source: base.sourceContext.binding, evidence: base.sourceContext.evidence };
    } finally {
      options.signal?.removeEventListener('abort', abort); unsubscribe(); session.dispose(); this.sessions.delete(session);
    }
  }
}

export class FakeDiagramEditRuntime implements DiagramGenerator {
  async generate(request: DiagramGenerationRequest, options: GenerationOptions) {
    options.signal?.throwIfAborted();
    const base = request.context!.diagram, instruction = request.instruction.replace(/[\r\n]/g, ' ');
    options.onAgentSession?.(`fake-agent-${crypto.randomUUID()}`);
    if (request.llmSessionId) options.onAgentContext?.(AgentContext.fromMessages(request.llmSessionId, [
      ...(request.agentContext?.messages ?? []),
      { role: 'user', content: [{ type: 'text', text: request.instruction }], timestamp: 0 },
      { role: 'assistant', content: [{ type: 'text', text: `Generated diagram for: ${request.instruction}` }], timestamp: 0 },
    ]).toSnapshot());
    options.onProgress?.('Generating fake diagram edit');
    if (!request.baseRevisionId) return {
      ascii: `[created: ${instruction}]`, structureKind: 'diagram' as const, mappings: [],
      source: base.sourceContext.binding, evidence: base.sourceContext.evidence
    };
    const lines = base.content.ascii.split('\n');
    const ranges = request.editRanges?.length ? request.editRanges : request.editRange ? [request.editRange] : [];
    if (ranges.length) for (const range of ranges) lines[range.startLine - 1] += ` [edited: ${instruction}]`;
    else lines.push(`[edited: ${instruction}]`);
    const nodes = diagramContentNodes(base.content);
    return {
      ...(ranges.length ? { replacementRanges: ranges } : {}), nodeCorrespondence: Object.fromEntries(nodes.filter(node => nodes.filter(other => other.line === node.line).length === 1 && request.nodeRefs?.[node.id]).map(node => [request.nodeRefs![node.id], node.line])), ascii: lines.join('\n'),
      structureKind: base.content.structure.kind, ...(request.sourceMappings ? { mappings: [...base.sourceContext.mappings] } : {}),
      source: base.sourceContext.binding, evidence: base.sourceContext.evidence
    };
  }
  dispose() { }
}
