16:   stepId: string;
17:   prompt: string;
18:   signal?: AbortSignal;
19: }
20: 
21: /** Return only this turn's accepted submission. Honor signal for in-flight cancellation. */
22: export type AgentStepExecutor<T> = (request: AgentStepRequest) => Promise<T | undefined>;
23: 
24: export async function runAgentWorkflow<T>(
25:   workflow: AgentWorkflow<T>,
26:   execute: AgentStepExecutor<T>,
27:   options: { signal?: AbortSignal; onStepStart?(stepId: string): void } = {}
28: ): Promise<T> {
29:   if (!workflow.id.trim() || !workflow.steps.length) throw new Error("An agent workflow needs an id and at least one step");
30:   const ids = new Set<string>();
31:   for (const step of workflow.steps) {
32:     if (!step.id.trim() || ids.has(step.id)) throw new Error(`Invalid or duplicate workflow step: ${step.id}`);
33:     ids.add(step.id);
34:   }
35: 
36:   let previous: T | undefined;
37:   for (const step of workflow.steps) {
38:     options.signal?.throwIfAborted();
39:     options.onStepStart?.(step.id);
40:     await step.before?.(previous);
41:     options.signal?.throwIfAborted();
42:     const output = await execute({
43:       workflowId: workflow.id, stepId: step.id, prompt: step.prompt(previous), signal: options.signal
44:     });
45:     options.signal?.throwIfAborted();
46:     if (output === undefined) throw new Error(`${workflow.id}/${step.id} finished without an accepted submission`);
47:     await step.validate?.(output, previous);
48:     options.signal?.throwIfAborted();
49:     previous = output;
50:   }
51:   return previous!;
52: }

