99: export class FakeDiagramEditRuntime implements DiagramGenerator {
100:   async generate(request: DiagramGenerationRequest, options: GenerationOptions) {
101:     options.signal?.throwIfAborted();
102:     const base = request.context!.diagram, instruction = request.instruction.replace(/[\r\n]/g, ' ');
103:     options.onAgentSession?.(`fake-agent-${crypto.randomUUID()}`);
104:     if (request.llmSessionId) options.onAgentContext?.(AgentContext.fromMessages(request.llmSessionId, [
105:       ...(request.agentContext?.messages ?? []),
106:       { role: 'user', content: [{ type: 'text', text: request.instruction }], timestamp: 0 },
107:       { role: 'assistant', content: [{ type: 'text', text: `Generated diagram for: ${request.instruction}` }], timestamp: 0 },
108:     ]).toSnapshot());
109:     options.onProgress?.('Generating fake diagram edit');
110:     if (!request.baseRevisionId) return {
111:       ascii: `[created: ${instruction}]`, structureKind: 'diagram' as const, mappings: [],
112:       source: base.sourceContext.binding, evidence: base.sourceContext.evidence
113:     };
114:     const lines = base.content.ascii.split('\n');
115:     const ranges = request.editRanges?.length ? request.editRanges : request.editRange ? [request.editRange] : [];
116:     if (ranges.length) for (const range of ranges) lines[range.startLine - 1] += ` [edited: ${instruction}]`;
117:     else lines.push(`[edited: ${instruction}]`);
118:     const nodes = diagramContentNodes(base.content);
119:     return {
120:       ...(ranges.length ? { replacementRanges: ranges } : {}), nodeCorrespondence: Object.fromEntries(nodes.filter(node => nodes.filter(other => other.line === node.line).length === 1 && request.nodeRefs?.[node.id]).map(node => [request.nodeRefs![node.id], node.line])), ascii: lines.join('\n'),
121:       structureKind: base.content.structure.kind, ...(request.sourceMappings ? { mappings: [...base.sourceContext.mappings] } : {}),
122:       source: base.sourceContext.binding, evidence: base.sourceContext.evidence
123:     };
124:   }
125:   dispose() { }
126: }
